/* Independent C bit-mask DFS validator for pass-XII triangle compositions.
 * Input: graph records generated by tower_reference.py --generate.
 * All path/cycle searches use a fixed 32-bit visited mask, no NetworkX.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <stdbool.h>

static uint32_t adj[32],pmsk,cmask;
static int n;
static void pathdfs(int v,int target,uint32_t used,int len){
    if(v==target){pmsk|=(uint32_t)1<<len;return;}
    for(int w=0;w<n;w++)if((adj[v]>>w&1)&&!(used>>w&1))
      pathdfs(w,target,used|((uint32_t)1<<w),len+1);
}
static void cycdf(int start,int v,uint32_t used,int len){
    for(int w=0;w<n;w++)if(adj[v]>>w&1){
       if(w==start && len>=3){cmask|=(uint32_t)1<<len;}
       else if(w>start && !(used>>w&1))cycdf(start,w,used|((uint32_t)1<<w),len+1);
    }
}
static void print_mask(uint32_t mask){
    bool first=true;
    for(int i=0;i<32;i++)if(mask>>i&1){if(!first)putchar(',');printf("%d",i);first=false;}
}
static void types(FILE *f){
    char name[32];int p[3],e;
    while(fscanf(f,"%31s %d %d %d %d %d",name,&n,&p[0],&p[1],&p[2],&e)==6){
       if(n>31 || n<1 || e<0 || e>200){fprintf(stderr,"bad header\n");exit(3);}
       memset(adj,0,sizeof(adj));
       for(int i=0;i<e;i++){
          int a,b;if(fscanf(f,"%d %d",&a,&b)!=2 || a<0 || a>=n || b<0 || b>=n){exit(4);}
          adj[a]|=(uint32_t)1<<b;adj[b]|=(uint32_t)1<<a;
       }
       cmask=0;
       for(int v=0;v<n;v++)cycdf(v,v,(uint32_t)1<<v,1);
       printf("TYPE|%s|%d|",name,n);print_mask(cmask);
       for(int i=0;i<3;i++)for(int j=i+1;j<3;j++){
         pmsk=0;pathdfs(p[i],p[j],(uint32_t)1<<p[i],0);
         putchar('|');print_mask(pmsk);
       }
       putchar('\n');
    }
}
static const char names[]="ITSH";
static const int sizes[]={1,3,7,15};
static const int amin[]={0,1,2,3};
static const int amax[]={0,1,3,5};
static bool has_power(int lo,int hi){for(int p=4;p<=64;p*=2)if(lo<=p&&p<=hi)return true;return false;}
static void cases_k4(void){
    const char labels[]="ITSUH";
    const int orders[]={1,3,7,7,15};
    const int first[]={0,1,2,2,3};
    const int last[]={0,1,3,2,5};
    for(int a=0;a<5;a++)for(int b=a;b<5;b++)for(int c=b;c<5;c++){
      int N=orders[a]+orders[b]+orders[c];
      printf("K4|%c%c%c|%d|",labels[a],labels[b],labels[c],N);
      bool keep=false;
      for(int x=first[a];x<=last[a];x+=(a==2?1:(a==4?2:1)))
      for(int y=first[b];y<=last[b];y+=(b==2?1:(b==4?2:1)))
      for(int z=first[c];z<=last[c];z+=(c==2?1:(c==4?2:1))){
        if(!has_power(3+x+y+z,N)){
           if(keep)putchar(';');printf("%d,%d,%d",x,y,z);keep=true;
        }
      }
      if(!keep)putchar('-');
      putchar('\n');
    }
}
static void cases(void){
    for(int a=0;a<4;a++)for(int b=a;b<4;b++)for(int c=b;c<4;c++){
       int N=sizes[a]+sizes[b]+sizes[c];
       printf("CASE|%c%c%c|%d|",names[a],names[b],names[c],N);
       bool first=true;
       for(int x=amin[a];x<=amax[a];x+=(a>=2?amax[a]-amin[a]:1))
       for(int y=amin[b];y<=amax[b];y+=(b>=2?amax[b]-amin[b]:1))
       for(int z=amin[c];z<=amax[c];z+=(c>=2?amax[c]-amin[c]:1)){
         if(has_power(3+x+y+z,N))continue;
         if(!first)putchar(';');printf("%d,%d,%d",x,y,z);first=false;
       }
       if(first)putchar('-');putchar('\n');
    }
}
int main(int argc,char **argv){
    if(argc!=2){fprintf(stderr,"usage: %s graphs.txt\n",argv[0]);return 2;}
    FILE *f=fopen(argv[1],"r");if(!f){perror(argv[1]);return 2;}
    types(f);fclose(f);cases();cases_k4();return 0;
}
